import type { Assignee, Board, Task } from '../../shared/kanban.ts'

// Every change to the board goes through this reducer
export type BoardAction =
  | {
      type: 'addTask'
      /** Generated by the caller, so the server stores the task under the same id */
      taskId: string
      columnId: string
      title: string
    }
  | {
      /**
       * Places a task in a column at a position; covers both reordering and moving
       * between columns. Moving into the Completed column sets progress to 100.
       */
      type: 'moveTask'
      taskId: string
      toColumnId: string
      /** Position in the destination column once the move is done */
      toIndex: number
    }
  | {
      /** Edits from the task detail modal; fields left out stay as they are */
      type: 'updateTask'
      taskId: string
      changes: TaskChanges
    }
  | {
      type: 'deleteTask'
      taskId: string
    }
  | {
      /** A comment was added (+1) or deleted (-1); the comments themselves live in the modal */
      type: 'adjustCommentCount'
      taskId: string
      delta: number
    }

export type TaskChanges = Partial<Pick<Task, 'title' | 'description' | 'priority' | 'dueDate' | 'assignees'>>

const sameAssignees = (a: Task['assignees'], b: Task['assignees']) =>
  a.length === b.length && a.every((person, i) => person.id === b[i].id)

/** Id of the column holding a task, or the id itself when it's already a column id */
export function findColumnId(board: Board, id: string): string | undefined {
  if (board.columns[id]) return id
  return board.columnOrder.find((columnId) => board.columns[columnId].taskIds.includes(id))
}

/** Everyone assigned to at least one task, in board order of first appearance */
export function getTeamMembers(board: Board): Assignee[] {
  const members = new Map<string, Assignee>()
  for (const columnId of board.columnOrder) {
    for (const taskId of board.columns[columnId].taskIds) {
      for (const assignee of board.tasks[taskId].assignees) {
        if (!members.has(assignee.id)) members.set(assignee.id, assignee)
      }
    }
  }
  return [...members.values()]
}

export function boardReducer(board: Board, action: BoardAction): Board {
  switch (action.type) {
    case 'addTask': {
      const column = board.columns[action.columnId]
      const title = action.title.trim()
      if (!column || !title) return board

      const task: Task = {
        id: action.taskId,
        title,
        description: '',
        dueDate: null,
        priority: 'ok',
        progress: column.status === 'completed' ? 100 : 0,
        assignees: [],
        commentCount: 0,
        completedSubtaskCount: 0,
      }

      // New tasks go on top: the add form opens from the column header
      return {
        ...board,
        tasks: { ...board.tasks, [task.id]: task },
        columns: {
          ...board.columns,
          [column.id]: { ...column, taskIds: [task.id, ...column.taskIds] },
        },
      }
    }

    case 'moveTask': {
      const fromColumnId = findColumnId(board, action.taskId)
      const toColumn = board.columns[action.toColumnId]
      const task = board.tasks[action.taskId]
      if (!fromColumnId || !task || !toColumn) return board

      const fromColumn = board.columns[fromColumnId]
      const fromIndex = fromColumn.taskIds.indexOf(action.taskId)
      const isSameColumn = fromColumn.id === toColumn.id

      const remaining = isSameColumn
        ? fromColumn.taskIds.filter((id) => id !== action.taskId)
        : toColumn.taskIds
      const toIndex = Math.max(0, Math.min(action.toIndex, remaining.length))
      if (isSameColumn && toIndex === fromIndex) return board

      const toTaskIds = [...remaining.slice(0, toIndex), action.taskId, ...remaining.slice(toIndex)]

      // Arriving in Completed means the task is done
      const completesTask = !isSameColumn && toColumn.status === 'completed' && task.progress !== 100

      return {
        ...board,
        ...(completesTask && {
          tasks: { ...board.tasks, [task.id]: { ...task, progress: 100 } },
        }),
        columns: {
          ...board.columns,
          ...(!isSameColumn && {
            [fromColumn.id]: {
              ...fromColumn,
              taskIds: fromColumn.taskIds.filter((id) => id !== action.taskId),
            },
          }),
          [toColumn.id]: { ...toColumn, taskIds: toTaskIds },
        },
      }
    }

    case 'updateTask': {
      const task = board.tasks[action.taskId]
      if (!task) return board
      const { title, description, priority, dueDate, assignees } = action.changes
      // Same rule as the server: titles are trimmed and can't be empty
      const trimmedTitle = title?.trim()
      const next: Task = {
        ...task,
        ...(trimmedTitle && { title: trimmedTitle }),
        ...(description !== undefined && { description }),
        ...(priority && { priority }),
        // null is a real value here: it clears the due date
        ...(dueDate !== undefined && { dueDate }),
        ...(assignees && { assignees }),
      }
      const unchanged =
        next.title === task.title &&
        next.description === task.description &&
        next.priority === task.priority &&
        next.dueDate === task.dueDate &&
        sameAssignees(next.assignees, task.assignees)
      if (unchanged) return board
      return { ...board, tasks: { ...board.tasks, [task.id]: next } }
    }

    case 'adjustCommentCount': {
      const task = board.tasks[action.taskId]
      if (!task || action.delta === 0) return board
      const commentCount = Math.max(0, task.commentCount + action.delta)
      return { ...board, tasks: { ...board.tasks, [task.id]: { ...task, commentCount } } }
    }

    case 'deleteTask': {
      const columnId = findColumnId(board, action.taskId)
      if (!columnId || !board.tasks[action.taskId]) return board
      const column = board.columns[columnId]
      const { [action.taskId]: _deleted, ...tasks } = board.tasks
      return {
        ...board,
        tasks,
        columns: { ...board.columns, [columnId]: { ...column, taskIds: column.taskIds.filter((id) => id !== action.taskId) } },
      }
    }
  }
}
